// 練習用の小さなハッシュ関数(本物のサイトでは使えない。しくみを見るためのもの)
function hash(text) {
  let h = 2166136261;
  for (const ch of text) {
    h ^= ch.codePointAt(0);
    h = Math.imul(h, 16777619) >>> 0;
  }
  return h.toString(16).padStart(8, "0");
}

const admin = { salt: "Qz81", hash: hash("Qz81" + "Secr3t!") };

function adminLogin(admin, password) {
  return hash(admin.salt + password) === admin.hash;
}

console.log(adminLogin(admin, "Secr3t!"));

